# Generated by GPT-6.2 Astra
import hashlib
import json
from collections import Counter
from zipfile import ZipFile

from character_data import TRAIN_ARCHIVE, read_records, read_variant, training_members
from character_model import DATASET, MODEL56, ROOT, inference_scores, winner
from character_twin import Twin, input_pixels


def score_records(records, model):
    sections = {"test": [], "validation": [], "reference": []}
    for row in records:
        if row["kind"] == "reference":
            section = "reference"
        elif row["split"] in ("val", "test"):
            section = "validation" if row["split"] == "val" else "test"
        else:
            continue
        pixels = input_pixels(
            row["file"], "raw" if row["kind"] == "camera" else "card", 56
        )
        scores = inference_scores(pixels, model)
        pred, score = winner(scores)
        sections[section].append(
            dict(
                sample_id=row["sample_id"],
                source_group=row["source_group"],
                label=row["class_id"],
                reported=pred + 1,
                score=score,
                scores=scores.astype(int).tolist(),
            )
        )
    return sections


def main():
    manifest = json.loads((MODEL56 / "splits.json").read_text("utf8"))
    evaluation = json.loads((MODEL56 / "evaluation.json").read_text("utf8"))
    records = {r["sample_id"]: r for r in read_records(DATASET, ROOT / "captures")}
    blocked = {
        r["source_group"]
        for r in json.loads((DATASET / "评测排除.json").read_text("utf8"))
    }
    real = {
        "web_image",
        "web_motion_poster",
        "web_cover_crop",
        "gif_frame",
        "video_frame",
        "verified_video_frame",
        "camera",
    }
    rows = []
    splits_by_hash = {}
    for original in manifest:
        row = records[original["sample_id"]]
        if any(
            row.get(k) != original.get(k)
            for k in ("source_group", "class_id", "split", "sha256")
        ):
            raise ValueError(f"Frozen split mismatch: {row['sample_id']}")
        sha = hashlib.sha256(row["file"].read_bytes()).hexdigest()
        if (
            sha != row["sha256"]
            or splits_by_hash.setdefault(sha, row["split"]) != row["split"]
        ):
            raise ValueError(
                f"Original hash mismatch or cross-split image: {row['sample_id']}"
            )
        if row["split"] != "train" and (
            row["kind"] not in real or row["source_group"] in blocked
        ):
            raise ValueError(f"Ineligible evaluation image: {row['sample_id']}")
        rows.append(row)
    with ZipFile(TRAIN_ARCHIVE) as archive:
        members = training_members(archive, rows)
        for member in members:
            read_variant(archive, member)
    counts = Counter(r["class_id"] for r in members)
    if counts != {i: 768 for i in range(1, 16)} or len(
        {r["sha256"] for r in members}
    ) != len(members):
        raise ValueError(
            "Role augmentation archive differs from the frozen training set"
        )
    twin = Twin(MODEL56)
    scores = score_records(rows, twin.model)
    for key, results in scores.items():
        if results != evaluation[key]:
            raise ValueError(
                f"Integer predictions differ from the published {key} results"
            )
    print(
        f"PASS {len(rows)} original hashes, {len(members)} train-only PNGs and all 15 role scores."
    )
    for section, results in scores.items():
        correct = sum(r["reported"] == r["label"] for r in results)
        print(f"{section}: {correct}/{len(results)}")


if __name__ == "__main__":
    main()
